ASSUMPTIONS = {
    "cam": "Cam-bank finite-feature camera. Cone-bank and phase-cylinder use this mechanical-neighborhood framing, not a recovered cone lens or gear motion.",
    "bank": "Ordered bank finite-source family. Hand-setting, moving-bank and phase-right use the same bank-facing camera; hidden channel inputs are held, not historically recovered motion.",
    "crank": "Finite crank/paper/marker camera. Wide pen and composite inset reuse output-region framing; their historical zoom and setup are not identified.",
    "macro": "Override-free square-pixel front-paper joint camera retained despite 133.1336243413906px CPU residual. Rejected pitch-only 34.608px fit failed upper-body checks at 130..139px; no detached marker/head overrides used.",
    "plaque": "Proper above-plane native presentation, not a mirror waiver. Coplanar fit does not constrain hardware depth: cap shift141.304px and contour331.797px remain failed diagnostics.",
    "fixture": "Whole-body fixture branch uses actual complete input, not independent paper/pen shifts. Source camera remains a conditional proposal.",
    "static": "Chosen feasible minus18mm fixed51 state, all435/21-spring CPU export, not historical settings. Original observed per-frame whole-machine camera takes precedence over the candidate camera.",
    "photo": "Source5574 physical photo branchB1. Same-image book/poster layout donor; source residuals remain conditional and no full435/GPU qualification claimed.",
}

def resize_camera(camera, donor_rect, rect):
    """Preserve donor photo normalized framing (chosen resizing assumption)."""
    result = copy.deepcopy(camera)
    if result.get("principalPointViewportPixels"):
        px, py = result["principalPointViewportPixels"]
        result["principalPointViewportPixels"] = [px * rect[2] / donor_rect[2], py * rect[3] / donor_rect[3]]
    return result


def main():
    data = common.load_observations("NAsM30MAHLg")
    common.validate_current_generation_inputs(data, Path(__file__))
    diagnostics = {}
    for key, candidate in CANDIDATES.items():
        diagnostics[key] = {"evidencePath": candidate["evidencePath"], "sha256": candidate["sha256"],
                            "originalBranchResiduals": candidate["cpuDiagnostics"],
                            "measurementScope": "retained original CPU candidate only; reframing/input reuse unmeasured"}

    def views_for(frame):
        output = []
        originals = common.source_views(frame, data)
        primary = [v for v in originals if not v["id"].startswith(("right-", "end-"))]
        shot = next(s for s in data["shots"] if s["id"] == frame["shotId"])
        for index, original in enumerate(originals):
            identity = original["id"]
            key = ALIASES.get(identity, identity)
            candidate = CANDIDATES[key]
            rect = copy.deepcopy(original["rectSourcePixels"])
            if "-operation-" in identity:
                # Original census has the parent ROI for all three subviews.
                # Actual independent paper-support cut measurements give these
                # distinct direct-camera source rectangles, not three overlays.
                rect = copy.deepcopy(candidate["rect"])
            original_camera = common.compact_camera(original.get("camera"))
            camera = original_camera or resize_camera(candidate["camera"], candidate["rect"], rect)
            evidence = (candidate["evidencePath"] + " sha256=" + candidate["sha256"] + "; " +
                        ASSUMPTIONS.get(key, "Distinct actual source-photo chosen camera and complete51 input retained.") +
                        " All51 inputs remain chosen/unobserved. No stage or GPU pass. No source motion invented.")
            if rect != candidate["rect"] and not original_camera:
                evidence += " Camera principal point resized in viewport-local coordinates; normalized donor framing is a chosen approximation, not a refit."
            if identity == "end-page-by-page":
                evidence += " No independently fitted page-by-page camera: whole-machine source framing is a reachable baseline for this photographed machine; exact photo pose/composition remains unmeasured."
            if original_camera:
                camera_kind = "source-transfer"
                camera_family = "intro:observed:" + frame["shotId"] + ":" + identity
                camera_evidence = "Retained own Intro source-derived camera family at decoded PTS, including held/registered calibration; not an independently fitted target-exposure camera. Original CPU residual/status retained, no stage/GPU acceptance."
            else:
                camera_kind = "source-transfer"
                if identity == "end-page-by-page" or identity in ("cone-bank", "phase-cylinder-left"):
                    camera_kind = "source-informed-framing"
                camera_family = "intro:retained:" + key + ":" + candidate["sha256"] + ":" + identity
                camera_evidence = candidate["evidencePath"] + " sha256=" + candidate["sha256"]
                if camera_kind == "source-informed-framing":
                    camera_evidence += "; donor branch used as neutral source-informed framing, not a measurement of this source view."
                else:
                    camera_evidence += "; one retained conditional source-fit branch held/transferred across this view family, not independently refitted at each exposure. Original failure/residual diagnostics retained."
                if rect != candidate["rect"]:
                    camera_evidence += " Normalized viewport resizing is chosen, not a source refit."
                camera_evidence += " Fixed donor camera within this identity/family; historical camera motion unknown."
            view = {"id": identity, "rectSourcePixels": rect,
                    "presentation": original.get("presentation", candidate["presentation"]) if original_camera else candidate["presentation"],
                    "camera": camera, "input": common.compact_input(candidate["input"]),
                    "provenance": common.chosen_provenance(evidence)}
            view["cameraProvenance"] = {"kind": camera_kind, "evidence": camera_evidence, "family": camera_family}
            view["cameraContinuityFamily"] = camera_family
            warp = common.resolve_warp(original)
            if warp:
                view["imagePlaneWarp"] = warp
            composite = common.compact_composite(original)
            if composite:
                view["composite"] = composite
            elif len(primary) > 1 and original in primary and "crossfade" in shot["id"]:
                # Temporal weights are chosen feasible presentation, NOT an
                # independently measured source photometric opacity.
                duration = shot["endSeconds"] - shot["startSeconds"]
                progress = max(0, min(1, (frame["timeSeconds"] - shot["startSeconds"]) / duration))
                n = primary.index(original)
                weight = (1 - progress if n == 0 else progress / (len(primary) - 1))
                view["composite"] = {"mode": "crossfade", "groupId": shot["id"], "imageLayerId": identity, "opacity": weight}
                view["provenance"]["evidence"] += " Crossfade weights chosen linear in observed boundary time, not source-measured alpha."
            output.append(view)
        return output

    track = common.build_track(data, views_for, [
        "All required shots, integer seconds, changes and layout/landmark keys retained; original observed landmarks and decoded PTS unchanged.",
        "All montage views54..80, two-view68 composite, three gearing panels, five right-side photos, plaque and all eight endcard photographs remain required.",
        "Frozen feasible complete51 candidates are held by shot; no source historical input recovery or inferred crank speed. Unobserved moving-source motion is a staged-error measurement question, not an exemption.",
        "Source photo/camera/input family candidates can be used despite original strict2% failures. Coverage complete means rows have renderable approximations, not50/20/10/5% image error acceptance.",
        "No null machine views or unsupported row intervals. Page-by-page photo, cone/phase reframing, inset zoom and photometric crossfade remain explicitly chosen baselines, not matched witnesses.",
    ])
    track["cpuDiagnostics"] = diagnostics
    track["source"] = copy.deepcopy(data["source"])
    path = common.write_track(track)
    print(path)


